// The app's database (OpenSpec change native-app-foundation D4): the part of Dexie's API
// the shared modules call (src/storage/surface.json, generated by
// scripts/dexie-surface.mjs), on SQLite. db.ts declares its schema on a Dexie instance
// as always and hands it to the platform port (`platform.database`); the app answers
// with this adapter, so `db.tasks.where('project_id').equals(id).toArray()` and
// `db.transaction('rw', …, async () => …)` run here unchanged, and the web keeps
// Dexie on IndexedDB.
//
// - Rows are JSON text; a read is one JSON.parse of the result (no structured clone),
//   so every call gets objects of its own. Values JSON cannot hold faithfully (a Blob,
//   a CryptoKey, a Map) are refused when written. A property whose value is undefined
//   is dropped, where IndexedDB keeps it.
// - A where() or orderBy() on an index is a SQL query on that index (schema.ts).
// - A transaction is a SQLite transaction. Calls made inside it, across awaits, run on
//   it (scope.ts); a transaction started inside another joins it, as in Dexie. Calls
//   from outside wait until it ends, one at a time, as IndexedDB queues them. Every
//   statement runs on the connection's thread (op-sqlite), so the JS thread is free
//   while SQLite works.
// - After each committed write, onChange listeners get the names of the stores it
//   changed (dexie-react-hooks and liveQuery are not live here; the app's screens read
//   again on a change).
import type Dexie from 'dexie'
import { currentScope, Lock, runInScope, type Scope } from './scope'
import { columnOf, ddl, quote, storesOf, type Store } from './schema'
import type { Sql, SqlConnection, Value } from './sql'

type Row = Record<string, unknown>
type Key = string | number
type Change = (stores: ReadonlySet<string>) => void

/** The schema the file was last brought up to (schema.ts's stores, as JSON). */
const SCHEMA = quote('opentodo:schema')

/** A value JSON keeps as it is: refuse the rest rather than store `{}` in its place. */
function plain(this: unknown, _key: string, value: unknown): unknown {
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    const proto = Object.getPrototypeOf(value)
    if (proto !== Object.prototype && proto !== null) {
      throw new DOMExceptionLike(`storage: a ${(value as object).constructor?.name ?? 'value'} cannot be stored on this device`, 'DataCloneError')
    }
  }
  if (typeof value === 'number' && !Number.isFinite(value)) throw new DOMExceptionLike('storage: a number that is not finite cannot be stored', 'DataCloneError')
  return value
}

class DOMExceptionLike extends Error {
  constructor(message: string, name: string) {
    super(message)
    this.name = name
  }
}

const isKey = (k: unknown): k is Key => typeof k === 'string' || (typeof k === 'number' && !Number.isNaN(k))

function valueAt(row: unknown, path: string): unknown {
  let v = row
  for (const part of path.split('.')) {
    if (v === null || typeof v !== 'object') return undefined
    v = (v as Row)[part]
  }
  return v
}

/** IndexedDB's order of keys (Dexie's cmp): numbers, then strings, then arrays. */
export function compareKeys(a: unknown, b: unknown): number {
  const rank = (v: unknown) => (typeof v === 'number' ? 1 : typeof v === 'string' ? 3 : Array.isArray(v) ? 5 : NaN)
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (Array.isArray(a) && Array.isArray(b)) {
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      const c = compareKeys(a[i], b[i])
      if (c !== 0) return c
    }
    return a.length - b.length
  }
  return (a as Key) < (b as Key) ? -1 : (a as Key) > (b as Key) ? 1 : 0
}

const isMinKey = (v: unknown) => v === -Infinity
const isMaxKey = (v: unknown) => Array.isArray(v)

/** A condition on index columns, as SQL text with its parameters. */
interface Condition { sql: string; params: Value[] }

/**
 * `cols op bound` for a key range on an index, compound or not. A bound may hold
 * Dexie.minKey (-Infinity) or Dexie.maxKey ([[]] where arrays are keys): the tuple is
 * cut there, since every key compares above or below it.
 */
function rangeCondition(cols: string[], bound: unknown, lower: boolean, inclusive: boolean): Condition | 'all' | 'none' {
  const parts = cols.length > 1 ? (bound as unknown[]) : [bound]
  let k = parts.findIndex((p) => isMinKey(p) || isMaxKey(p))
  let incl = inclusive
  if (k >= 0) {
    // (x…, min) as a lower bound is "prefix ≥ x…", as an upper bound "prefix < x…"; max the other way round.
    const min = isMinKey(parts[k])
    incl = lower === min
    if (k === 0) return incl ? 'all' : 'none'
  } else {
    k = parts.length
  }
  const left = cols.slice(0, k)
  const values = parts.slice(0, k) as Value[]
  const op = lower ? (incl ? '>=' : '>') : (incl ? '<=' : '<')
  const l = left.length === 1 ? left[0] : `(${left.join(', ')})`
  const r = left.length === 1 ? '?' : `(${left.map(() => '?').join(', ')})`
  return { sql: `${l} ${op} ${r}`, params: values }
}

export interface SqliteDatabase {
  readonly name: string
  readonly tables: SqliteTable[]
  table(name: string): SqliteTable
  transaction(mode: string, ...rest: unknown[]): Promise<unknown>
  on(event: string, fn: unknown): void
  open(): Promise<SqliteDatabase>
  close(): void
  /** Closes the database and deletes its file (sign-out). */
  delete(): Promise<void>
  /** Called after every committed write with the stores it changed; returns the unsubscribe. */
  onChange(fn: Change): () => void
}

class Database implements SqliteDatabase {
  readonly tables: SqliteTable[]
  private connection: Promise<SqlConnection> | null = null
  private handle: SqlConnection | null = null
  private readonly lock = new Lock()
  private readonly listeners = new Set<Change>()

  constructor(readonly name: string, stores: Store[], private readonly sql: Sql) {
    this.tables = stores.map((s) => new SqliteTable(this, s))
    for (const t of this.tables) Object.defineProperty(this, t.name, { value: t, enumerable: true })
  }

  private file() {
    return `${this.name}.sqlite`
  }

  /** The open connection, with every store created or brought up to the declared schema. */
  connect(): Promise<SqlConnection> {
    this.connection ??= (async () => {
      const c = this.sql.open(this.file())
      this.handle = c
      // WAL with normal sync: a commit survives the app being killed; only a power loss
      // can take the last commits, never corrupt the file.
      await c.column('PRAGMA journal_mode = WAL')
      await c.run('PRAGMA synchronous = NORMAL')
      // The schema is brought up to the declared one only when it changed since the
      // last open: a cold start reads one row instead of checking every table.
      const declared = JSON.stringify(this.tables.map((t) => t.store))
      const [stored] = await c.column(`SELECT sig FROM ${SCHEMA}`).catch(() => [null])
      if (stored !== declared) {
        await c.run('BEGIN IMMEDIATE')
        try {
          for (const t of this.tables) {
            const existing = new Set((await c.column(`SELECT name FROM pragma_table_xinfo(?)`, [t.name])) as string[])
            for (const statement of ddl(t.store, existing)) await c.run(statement)
          }
          await c.run(`CREATE TABLE IF NOT EXISTS ${SCHEMA} (sig TEXT NOT NULL)`)
          await c.run(`DELETE FROM ${SCHEMA}`)
          await c.run(`INSERT INTO ${SCHEMA} (sig) VALUES (?)`, [declared])
          await c.run('COMMIT')
        } catch (e) {
          await c.run('ROLLBACK').catch(() => undefined)
          throw e
        }
      }
      return c
    })()
    return this.connection
  }

  table(name: string): SqliteTable {
    const t = this.tables.find((x) => x.name === name)
    if (!t) throw new Error(`storage: no table ${name}`)
    return t
  }

  /**
   * Runs `fn` on the connection: at once inside this database's running transaction,
   * else after everything queued before it, in a transaction of its own when it writes.
   */
  run<T>(write: string | null, fn: (c: SqlConnection) => Promise<T>): Promise<T> {
    const scope = currentScope(this)
    if (scope) {
      if (write) scope.changed.add(write)
      return this.connect().then(fn)
    }
    return this.lock.run(async () => {
      const c = await this.connect()
      if (!write) return fn(c)
      await c.run('BEGIN IMMEDIATE')
      let result: T
      try {
        result = await fn(c)
        await c.run('COMMIT')
      } catch (e) {
        await c.run('ROLLBACK').catch(() => undefined)
        throw e
      }
      this.emit(new Set([write]))
      return result
    })
  }

  transaction(_mode: string, ...rest: unknown[]): Promise<unknown> {
    const fn = rest[rest.length - 1] as () => unknown
    if (typeof fn !== 'function') return Promise.reject(new TypeError('storage: transaction() needs a function'))
    // Inside a running transaction: the same one, as Dexie runs a nested transaction.
    if (currentScope(this)) return Promise.resolve().then(fn)
    return this.lock.run(async () => {
      const c = await this.connect()
      const scope: Scope = { owner: this, changed: new Set(), done: false }
      await c.run('BEGIN IMMEDIATE')
      let result: unknown
      try {
        result = await runInScope(scope, fn)
        scope.done = true
        await c.run('COMMIT')
      } catch (e) {
        scope.done = true
        await c.run('ROLLBACK').catch(() => undefined)
        throw e
      }
      if (scope.changed.size) this.emit(scope.changed)
      return result
    })
  }

  private emit(stores: ReadonlySet<string>) {
    for (const fn of [...this.listeners]) {
      try { fn(stores) } catch { /* a listener's failure is its own */ }
    }
  }

  onChange(fn: Change): () => void {
    this.listeners.add(fn)
    return () => { this.listeners.delete(fn) }
  }

  // One process: no other instance can open a newer schema (db.ts's versionchange).
  on(): void {}

  async open(): Promise<SqliteDatabase> {
    await this.connect()
    return this
  }

  close(): void {
    this.handle?.close()
    this.handle = null
    this.connection = null
  }

  delete(): Promise<void> {
    return this.lock.run(async () => {
      await this.connection?.catch(() => undefined)
      this.close()
      this.sql.remove(this.file())
    })
  }
}

export class SqliteTable {
  readonly name: string
  private readonly t: string

  constructor(readonly db: Database, readonly store: Store) {
    this.name = store.name
    this.t = quote(store.name)
  }

  /** The columns of an index by its name (`project_id`, `[a+b]`, `:id`, the key path). */
  columnsOf(index: string): string[] {
    if (index === ':id' || index === this.store.key) return ['pk']
    const found = this.store.indexes.find((i) => i.name === index)
    if (!found) throw Object.assign(new Error(`KeyPath ${index} on object store ${this.name} is not indexed`), { name: 'SchemaError' })
    return found.paths.map((p) => (p === this.store.key ? 'pk' : columnOf(p)))
  }

  keyOf(row: Row): Key {
    const k = valueAt(row, this.store.key)
    if (!isKey(k)) throw Object.assign(new Error(`storage: ${this.name}: the row has no valid key at ${this.store.key}`), { name: 'DataError' })
    return k
  }

  /** The rows of a SELECT whose first column is `json`, parsed in one go. */
  async rows(c: SqlConnection, select: string, params: Value[], order: string): Promise<Row[]> {
    const [text] = await c.column(`SELECT '[' || group_concat(json, ',' ORDER BY ${order}) || ']' FROM (${select})`, params)
    return text ? (JSON.parse(text as string) as Row[]) : []
  }

  get(key: unknown): Promise<Row | undefined> {
    if (!isKey(key)) return Promise.reject(Object.assign(new Error('storage: get() takes a key'), { name: 'DataError' }))
    return this.db.run(null, async (c) => {
      const [json] = await c.column(`SELECT json FROM ${this.t} WHERE pk = ?`, [key])
      return json == null ? undefined : (JSON.parse(json as string) as Row)
    })
  }

  bulkGet(keys: readonly unknown[]): Promise<(Row | undefined)[]> {
    if (keys.length === 0) return Promise.resolve([])
    return this.db.run(null, async (c) => {
      const found = await this.rows(c, `SELECT json, pk FROM ${this.t} WHERE pk IN (SELECT value FROM json_each(?))`, [JSON.stringify(keys.filter(isKey))], 'pk')
      const byKey = new Map<unknown, Row>(found.map((r) => [valueAt(r, this.store.key), r]))
      return keys.map((k) => byKey.get(k))
    })
  }

  /** Gives rows of an auto-increment store without a key the next keys, as IndexedDB does. */
  private async assignKeys(c: SqlConnection, rows: readonly Row[]): Promise<Row[]> {
    if (!this.store.auto || rows.every((r) => valueAt(r, this.store.key) !== undefined)) return rows as Row[]
    const [seq] = await c.column(`SELECT max(coalesce((SELECT seq FROM sqlite_sequence WHERE name = ?), 0), coalesce((SELECT max(pk) FROM ${this.t}), 0))`, [this.name])
    let next = Number(seq ?? 0)
    return rows.map((r) => {
      if (valueAt(r, this.store.key) !== undefined) return r
      next += 1
      return { ...r, [this.store.key]: next }
    })
  }

  private write(rows: readonly Row[], replace: boolean): Promise<Key[]> {
    return this.db.run(this.name, async (c) => {
      const keyed = await this.assignKeys(c, rows)
      const keys = keyed.map((r) => this.keyOf(r))
      const verb = replace ? 'INSERT OR REPLACE' : 'INSERT'
      const path = `'$."${this.store.key}"'`
      await c.run(`${verb} INTO ${this.t} (pk, json) SELECT json_extract(value, ${path}), value FROM json_each(?)`, [JSON.stringify(keyed, plain)])
      return keys
    })
  }

  async put(row: Row): Promise<Key> {
    const [key] = await this.write([row], true)
    // Dexie sets a generated key on the object it was given (Table.add/put).
    if (this.store.auto && valueAt(row, this.store.key) === undefined) row[this.store.key] = key
    return key
  }

  async bulkPut(rows: readonly Row[]): Promise<Key | undefined> {
    if (rows.length === 0) return undefined
    return (await this.write(rows, true)).at(-1)
  }

  async bulkAdd(rows: readonly Row[]): Promise<Key | undefined> {
    if (rows.length === 0) return undefined
    return (await this.write(rows, false)).at(-1)
  }

  delete(key: unknown): Promise<void> {
    return this.db.run(this.name, async (c) => { await c.run(`DELETE FROM ${this.t} WHERE pk = ?`, [key as Value]) })
  }

  bulkDelete(keys: readonly unknown[]): Promise<void> {
    if (keys.length === 0) return Promise.resolve()
    return this.db.run(this.name, async (c) => { await c.run(`DELETE FROM ${this.t} WHERE pk IN (SELECT value FROM json_each(?))`, [JSON.stringify(keys)]) })
  }

  clear(): Promise<void> {
    return this.db.run(this.name, async (c) => { await c.run(`DELETE FROM ${this.t}`) })
  }

  /** Dexie's update: changes by key path, undefined removes the property; 1 when the row exists. */
  update(key: unknown, changes: Record<string, unknown>): Promise<number> {
    return this.db.run(this.name, async (c) => {
      const [json] = await c.column(`SELECT json FROM ${this.t} WHERE pk = ?`, [key as Value])
      if (json == null) return 0
      const row = JSON.parse(json as string) as Row
      for (const [path, value] of Object.entries(changes)) {
        if (path === this.store.key) throw Object.assign(new Error('storage: update() cannot change the primary key'), { name: 'ConstraintError' })
        const parts = path.split('.')
        let target = row
        for (const p of parts.slice(0, -1)) target = (target[p] ??= {}) as Row
        const last = parts[parts.length - 1]
        if (value === undefined) delete target[last]
        else target[last] = value
      }
      await c.run(`UPDATE ${this.t} SET json = ? WHERE pk = ?`, [JSON.stringify(row, plain), key as Value])
      return 1
    })
  }

  count(): Promise<number> {
    return this.toCollection().count()
  }

  toArray(): Promise<Row[]> {
    return this.toCollection().toArray()
  }

  async each(fn: (row: Row) => void): Promise<void> {
    for (const row of await this.toArray()) fn(row)
  }

  filter(fn: (row: Row) => boolean): Collection {
    return this.toCollection().filter(fn)
  }

  orderBy(index: string): Collection {
    return new Collection(this, this.columnsOf(index), null)
  }

  where(index: string): WhereClause {
    return new WhereClause(this, this.columnsOf(index))
  }

  toCollection(): Collection {
    return new Collection(this, ['pk'], null)
  }

  /**
   * The phone's own query (lists.ts): the rows matching a SQL condition on the store's
   * columns (`"i:<path>"`, pk), in key order. Not part of Dexie's API.
   */
  select(where: string, params: Value[] = []): Promise<Row[]> {
    return this.db.run(null, (c) => this.rows(c, `SELECT json, pk FROM ${this.t} WHERE ${where}`, params, 'pk'))
  }
}

export class WhereClause {
  constructor(private readonly table: SqliteTable, private readonly cols: string[]) {}

  private collection(c: Condition | 'all' | 'none'): Collection {
    return new Collection(this.table, this.cols, c === 'all' ? null : c === 'none' ? { sql: '0', params: [] } : c)
  }

  equals(value: unknown): Collection {
    const values = this.cols.length > 1 ? (value as Value[]) : [value as Value]
    return this.collection({ sql: this.cols.map((c) => `${c} = ?`).join(' AND '), params: values })
  }

  anyOf(values: readonly unknown[]): Collection {
    if (this.cols.length > 1) throw new Error('storage: anyOf() on a compound index is not supported')
    if (values.length === 0) return this.collection('none')
    return this.collection({ sql: `${this.cols[0]} IN (SELECT value FROM json_each(?))`, params: [JSON.stringify(values.filter(isKey))] })
  }

  above(value: unknown): Collection {
    return this.collection(rangeCondition(this.cols, value, true, false))
  }

  between(lower: unknown, upper: unknown, includeLower = true, includeUpper = false): Collection {
    const lo = rangeCondition(this.cols, lower, true, includeLower)
    const hi = rangeCondition(this.cols, upper, false, includeUpper)
    if (lo === 'none' || hi === 'none') return this.collection('none')
    if (lo === 'all') return this.collection(hi)
    if (hi === 'all') return this.collection(lo)
    return this.collection({ sql: `${lo.sql} AND ${hi.sql}`, params: [...lo.params, ...hi.params] })
  }
}

export class Collection {
  private dir: 'ASC' | 'DESC' = 'ASC'
  private filters: ((row: Row) => boolean)[] = []
  private max: number | null = null

  constructor(private readonly table: SqliteTable, private readonly cols: string[], private readonly condition: Condition | null) {}

  private copy(change: (c: Collection) => void): Collection {
    const c = new Collection(this.table, this.cols, this.condition)
    c.dir = this.dir
    c.filters = [...this.filters]
    c.max = this.max
    change(c)
    return c
  }

  filter(fn: (row: Row) => boolean): Collection {
    return this.copy((c) => { c.filters.push(fn) })
  }

  reverse(): Collection {
    return this.copy((c) => { c.dir = c.dir === 'ASC' ? 'DESC' : 'ASC' })
  }

  limit(n: number): Collection {
    return this.copy((c) => { c.max = n })
  }

  /** WHERE and ORDER BY of the index range: only rows the index holds (every column a key). */
  private query(what: string): { sql: string; params: Value[]; order: string } {
    const present = this.cols.filter((c) => c !== 'pk').map((c) => `${c} IS NOT NULL`)
    const where = [...present, ...(this.condition ? [this.condition.sql] : [])]
    const keys = this.cols.includes('pk') ? this.cols : [...this.cols, 'pk']
    const order = keys.map((c) => `${c} ${this.dir}`).join(', ')
    const limit = this.max !== null && this.filters.length === 0 ? ` LIMIT ${Math.max(0, Math.floor(this.max))}` : ''
    return {
      sql: `SELECT ${what}${keys.filter((c) => c !== 'pk').map((c) => `, ${c}`).join('')}, pk FROM ${quote(this.table.name)}${where.length ? ` WHERE ${where.join(' AND ')}` : ''} ORDER BY ${order}${limit}`,
      params: this.condition?.params ?? [],
      order,
    }
  }

  private matching(rows: Row[]): Row[] {
    if (this.filters.length === 0) return rows
    const out = rows.filter((r) => this.filters.every((f) => f(r)))
    return this.max === null ? out : out.slice(0, Math.max(0, this.max))
  }

  toArray(): Promise<Row[]> {
    return this.table.db.run(null, async (c) => {
      const q = this.query('json')
      return this.matching(await this.table.rows(c, q.sql, q.params, q.order))
    })
  }

  async count(): Promise<number> {
    if (this.filters.length) return (await this.toArray()).length
    return this.table.db.run(null, async (c) => {
      const q = this.query('1')
      const [n] = await c.column(`SELECT count(*) FROM (${q.sql})`, q.params)
      return Number(n ?? 0)
    })
  }

  async primaryKeys(): Promise<Key[]> {
    if (this.filters.length) return (await this.toArray()).map((r) => this.table.keyOf(r))
    return this.table.db.run(null, async (c) => {
      const q = this.query('1')
      const [keys] = await c.column(`SELECT json_group_array(pk ORDER BY ${q.order}) FROM (${q.sql})`, q.params)
      return JSON.parse((keys as string | null) ?? '[]') as Key[]
    })
  }

  async first(): Promise<Row | undefined> {
    return (await this.limit(1).toArray())[0]
  }

  last(): Promise<Row | undefined> {
    return this.reverse().first()
  }

  /** Dexie's sortBy: the rows sorted by the value at the key path, in IndexedDB's key order. */
  async sortBy(path: string): Promise<Row[]> {
    const order = this.dir === 'ASC' ? 1 : -1
    return (await this.toArray()).sort((a, b) => (compareKeys(valueAt(a, path), valueAt(b, path)) || 0) * order)
  }
}

/** The adapter for the schema `declared` (db.ts's OpenTodoDB), on the database file of its name. */
export function sqliteDatabase<D extends Dexie>(declared: D, sql: Sql): D & SqliteDatabase {
  return new Database(declared.name, storesOf(declared), sql) as unknown as D & SqliteDatabase
}
